import { test, expect } from '@playwright/test';

test.describe('Drawer/Slide-in Panel', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://your-application-url.com');
  });

  test('should open the drawer when the button is clicked', async ({ page }) => {
    await page.getByRole('button', { name: /open drawer/i }).click();
    const drawer = page.getByRole('dialog', { name: /drawer panel/i });
    await expect(drawer).toBeVisible();
  });

  test('should close the drawer when the close button is clicked', async ({ page }) => {
    await page.getByRole('button', { name: /open drawer/i }).click();
    const drawer = page.getByRole('dialog', { name: /drawer panel/i });
    await expect(drawer).toBeVisible();

    await drawer.getByRole('button', { name: /close/i }).click();
    await expect(drawer).toBeHidden();
  });
});
